#include <stdio.h>
/* ex05：序号位数 n 决定窗口上限——GBN 与 SR 的经典结论
 * GBN（后退 N 帧）：窗口 W <= 2^n - 1
 *     原因：若 W = 2^n，接收端无法区分「新帧」与「重传的旧帧」。
 * SR（选择重传）：窗口 W <= 2^(n-1)
 *     原因：收发窗口之和不能超过序号空间，否则同样无法区分新旧。
 * 这两个公式是 408 必背，且常以「给定 n 求最大窗口」的形式出现。*/
int main(void) {
    printf("%-6s %-12s %-18s %-18s %s\n", "n(位)", "序号空间", "GBN 最大窗口", "SR 最大窗口", "SR 接收窗口");
    printf("----------------------------------------------------------------------\n");
    for (int n = 2; n <= 5; n++) {
        int space = 1 << n;                 /* 2^n */
        int gbn = space - 1;
        int sr  = space / 2;                /* 2^(n-1) */
        printf("%-6d %-12d %-18d %-18d %d\n", n, space, gbn, sr, sr);
    }
    printf("----------------------------------------------------------------------\n");
    printf("举例说明「为什么 GBN 不能取 W = 2^n」：\n");
    printf("  n=2（序号 0..3），若 W=4：发送方连发 0,1,2,3；\n");
    printf("  接收端全收到并回 ACK，但 ACK 全部丢失 -> 发送方超时重传 0,1,2,3；\n");
    printf("  接收端看到序号 0，会以为这是「下一轮的 0」而不是「上一轮的重传 0」，\n");
    printf("  于是重复交付 —— 无法区分新旧，所以 W 必须 <= 2^n - 1。\n");
    printf("\nSR 为什么是 2^(n-1)：接收窗口也为 W，收发窗口之和 2W 不能超过 2^n，\n");
    printf("  故 W <= 2^(n-1)。SR 的代价是要缓存乱序到达的帧。\n");
    return 0;
}
